	if (pack_file) fclose(pack_file);
	vlog(use_pack ? "engine: using game.pck\n" : "engine: using loose game_data\n");
	const char *args[] = {
		use_pack ? "--main-pack" : "--path", use_pack ? pack_path : project_path,
